import 'package:didwebvh/src/model/log_entry.dart';

/// Result of a DID update, migration, or deactivation.
///
/// Usually contains one new entry; deactivation with active pre-rotation
/// produces two. Faithful port of Java `UpdateDidResult`.
class UpdateDidResult {
  /// Wraps the ordered list of [newEntries] produced by the operation.
  UpdateDidResult(List<LogEntry> newEntries)
      : newEntries = List.unmodifiable(newEntries);

  /// All new log entries generated by the operation (in order).
  final List<LogEntry> newEntries;

  /// The last (and usually only) new entry produced by the operation.
  LogEntry get logEntry => newEntries[newEntries.length - 1];
}
